const NEXT_DAY_STATISTICS_PATH = "outputs/decision/next_day_statistics.json";

function validateNextDayStatistics(payload, revision, loaded) {
  const original = loaded.sourcePayload || loaded.payload;
  const clock = new Date(Date.now() + 8 * 3600000);
  if (clock.getUTCHours() < 15) clock.setUTCDate(clock.getUTCDate() - 1);
  const closed = clock.toISOString().slice(0,10).replaceAll("-", "");
  const validDate = d => canonicalYmd(d) === d && d >= COMPACT_STATISTICS_WINDOW_START && d <= closed;
  executableProfitExpect(payload?.schema_version === "dc20_next_day_statistics_v1"
    && payload.promotion_start_signal_date === "20260910" && payload.profit_start_signal_date === "20260914"
    && isSha256(payload.engine_sha256)
    && payload.report_signal_date === revision.primary_d_signal_date
    && payload.report_signal_date === loaded.reportSignalDate
    && payload.report_signal_date === original.report_signal_date
    && validDate(payload.report_signal_date) && validDate(payload.as_of_date)
    && payload.as_of_date <= payload.report_signal_date
    && payload.as_of_date === (original.promotion?.status === "READY" ? original.promotion.as_of_date : original.report_signal_date),
    "次日统计日期与当前发布版本不一致");
  const bindings = payload.bindings;
  const rowsBinding = original.source_files?.find(item => item.path === "outputs/decision/primary_observation/rows.csv");
  const bound = (value, expected, unavailable) => expected == null
    ? value === null && unavailable : isSha256(value) && value === expected;
  executableProfitExpect(exactObjectKeys(bindings, ["window_sha256", "candidate_index_sha256", "candidate_activation_sha256", "primary_rows_sha256"])
    && isSha256(bindings.window_sha256) && bindings.window_sha256 === revision.compact_statistics_window_sha256
    && bound(bindings.candidate_index_sha256, revision.candidate_profit_index_sha256, payload.profit?.status === "UNAVAILABLE")
    && bound(bindings.candidate_activation_sha256, revision.candidate_profit_activation_sha256, payload.profit?.status === "UNAVAILABLE")
    && bound(bindings.primary_rows_sha256, rowsBinding?.sha256, payload.promotion?.status === "UNAVAILABLE"),
    "次日统计来源版本或指纹不一致");
  const result = {};
  for (const [name, ranks] of [["promotion", [1,2,3,"all"]], ["profit", [1,2]]]) {
    try {
      const section = payload[name];
      executableProfitExpect(section && ["READY", "UNAVAILABLE"].includes(section.status), "次日统计分区状态无效");
      if (section.status === "UNAVAILABLE") {
        executableProfitExpect(exactObjectKeys(section,["status","reason"]) && typeof section.reason === "string" && section.reason.trim(), "次日统计缺失说明无效");
        result[name] = {status:"unavailable", reason:section.reason};
        continue;
      }
      executableProfitExpect(exactObjectKeys(section,["status","as_of_date","cohorts"])
        && section.as_of_date === payload.as_of_date && Array.isArray(section.cohorts)
        && section.cohorts.length === ranks.length, "次日统计分区日期或名次数量无效");
      const keys = ["rank","count","valid","up","pending","missing","upRate","mean","median"];
      for (const [i,c] of section.cohorts.entries()) {
        executableProfitExpect(exactObjectKeys(c,name === "profit" ? [...keys,"limitVerified","limitHits","limitRate"] : keys)
          && c.rank === ranks[i] && ["count","valid","up","pending","missing"].every(k => Number.isSafeInteger(c[k]) && c[k] >= 0)
          && c.count === c.valid + c.pending + c.missing && c.up <= c.valid, "次日统计样本数或名次无效");
        executableProfitExpect(c.valid ? typeof c.upRate === "number" && Number.isFinite(c.upRate)
          && Math.abs(c.upRate-c.up/c.valid) < 1e-12
          && [c.mean,c.median].every(v => typeof v === "number" && Number.isFinite(v) && v > -1)
          : c.upRate === null && c.mean === null && c.median === null, "次日统计收益或分母无效");
        if (name === "profit") executableProfitExpect(["limitVerified","limitHits"].every(k => Number.isSafeInteger(c[k]) && c[k] >= 0)
          && c.limitHits <= c.limitVerified && c.limitVerified <= c.valid
          && (c.limitVerified ? typeof c.limitRate === "number" && Number.isFinite(c.limitRate)
            && Math.abs(c.limitRate-c.limitHits/c.limitVerified) < 1e-12 : c.limitRate === null), "次日统计涨停样本或分母无效");
      }
      result[name] = {status:"ready",asOf:section.as_of_date,cohorts:section.cohorts};
    } catch (error) { result[name] = {status:"unavailable",reason:String(error?.message || error)}; }
  }
  return result;
}

async function readNextDayStatisticsArtifact(revision) {
  executableProfitExpect(revision.next_day_statistics_url === NEXT_DAY_STATISTICS_PATH
    && isSha256(revision.next_day_statistics_sha256), "次日统计尚未绑定当前发布版本");
  const url = new URL(NEXT_DAY_STATISTICS_PATH, location.href);
  executableProfitExpect(location.protocol !== "file:" && url.origin === location.origin, "次日统计必须读取同源发布产物");
  // A tiny version-bound artifact replaces all historical market requests.
  // Retry transport failures only; never retry or relax a failed SHA check.
  for (let attempt=0; attempt<2; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    let bytes;
    try {
      url.searchParams.set("sha", revision.next_day_statistics_sha256);
      const response = await fetch(url.href, {cache:"no-cache", signal:controller.signal});
      if (!response.ok) {
        const error = new Error(`HTTP ${response.status}`); error.httpStatus=response.status; throw error;
      }
      bytes = new Uint8Array(await response.arrayBuffer());
    } catch (error) {
      if (attempt === 0 && (!error.httpStatus || [408,429,500,502,503,504].includes(error.httpStatus))) {
        clearTimeout(timer); await new Promise(resolve => setTimeout(resolve,800)); continue;
      }
      throw new Error(error?.name === "AbortError" ? "次日统计加载超时，请重试" : `次日统计读取失败：${String(error?.message || error)}`);
    } finally { clearTimeout(timer); }
    executableProfitExpect(await sha256Hex(bytes) === revision.next_day_statistics_sha256, "次日统计字节SHA256不一致");
    return strictJsonFromBytes(bytes,"次日统计");
  }
}

async function loadPublishedNextDayStatistics(loaded) {
  const revision = await publishedRevisionMetadata();
  const key = `${revision.head_sha}:${revision.next_day_statistics_sha256}`;
  const reads = state.nextDayStatisticsReads || (state.nextDayStatisticsReads = new Map());
  let pending = reads.get(key);
  if (!pending) { pending=readNextDayStatisticsArtifact(revision); reads.set(key,pending); }
  let payload;
  try { payload=await pending; }
  catch (error) { if(reads.get(key)===pending) reads.delete(key); throw error; }
  return validateNextDayStatistics(payload,revision,loaded);
}

async function loadNextDayMarketStatistics(loaded) {
  return (await loadPublishedNextDayStatistics(loaded)).promotion;

